function closeNav(){document.querySelectorAll('.ipm-menu.open').forEach(x=>x.classList.remove('open'));document.querySelectorAll('.ipm-subitem.mobile-open').forEach(x=>x.classList.remove('mobile-open'))}
function buildNav(){
 const nav=$('mainNav');if(!nav||nav.dataset.ipmPublic==='1')return;nav.dataset.ipmPublic='1';nav.className='main-nav ipm-public-nav';nav.innerHTML='';
 const build=items=>{const wrap=document.createElement('div');wrap.className='ipm-submenu';items.forEach(item=>{const row=document.createElement('div');row.className='ipm-subitem';const b=document.createElement('button');b.type='button';b.textContent=item.label;if(item.children){const a=document.createElement('span');a.className='ipm-arrow';a.textContent='›';b.appendChild(a);b.onclick=e=>{e.stopPropagation();document.querySelectorAll('.ipm-subitem.mobile-open').forEach(x=>{if(x!==row)x.classList.remove('mobile-open')});row.classList.toggle('mobile-open')};row.appendChild(b);row.appendChild(build(item.children))}else{b.onclick=e=>{e.stopPropagation();closeNav();publicRender(item.view)};row.appendChild(b)}wrap.appendChild(row)});return wrap};
 MENUS.forEach(item=>{const m=document.createElement('div');m.className='ipm-menu'+(item.view==='home'?' home':'');const b=document.createElement('button');b.type='button';b.textContent=item.label;if(item.children){const a=document.createElement('span');a.className='ipm-arrow';a.textContent='⌄';b.appendChild(a);b.onclick=e=>{e.stopPropagation();const was=m.classList.contains('open');document.querySelectorAll('.ipm-menu.open').forEach(x=>x.classList.remove('open'));m.classList.toggle('open',!was)};m.appendChild(b);m.appendChild(build(item.children))}else{b.onclick=()=>publicRender('home');m.appendChild(b)}nav.appendChild(m)});
 document.addEventListener('click',closeNav,{passive:true});
}
function hideAdmin(){
 document.querySelectorAll('[data-view="control"]').forEach(x=>x.remove());
 $('control')?.classList.remove('active');
 document.querySelectorAll('.suite-page,.suite-panel').forEach(el=>{const t=(el.textContent||'').toLowerCase();if(/api registry|konfigurasi|data flow|control center|problem engine|data ocean|future radar|forecast engine|scenario simulator|solution ai|accuracy engine|ai brain/.test(t))el.remove()});
}
function homeMarkup(){
 const hero=$('home')?.querySelector('.hero');if(!hero)return;
 [...$('home').children].forEach(el=>{if(el!==hero)el.remove()});
 const recent=[...hero.parentElement.querySelectorAll('.recent .issue-row')];
 const data=recent.length?recent.slice(0,3).map(x=>({title:x.querySelector('b')?.textContent||'Masalah terbaru',meta:x.querySelector('small')?.textContent||'Indonesia',tag:x.querySelector('.tag')?.textContent||'Masalah',icon:x.querySelector('.thumb')?.textContent||'⚠️'})):[{title:'Masalah infrastruktur di wilayah warga',meta:'Indonesia',tag:'Infrastruktur',icon:'🛣️'},{title:'Tekanan ekonomi rumah tangga',meta:'Indonesia',tag:'Ekonomi',icon:'🛒'},{title:'Akses pendidikan belum merata',meta:'Indonesia',tag:'Pendidikan',icon:'🏫'}];
 let h=`<div id="ipm-home-premium">
 <section class="ipm-section"><div class="ipm-head"><div><span class="ipm-kicker">POKOK MASALAH INDONESIA</span><h2>Apa yang sedang dihadapi masyarakat?</h2><p>Mulai dari masalah yang paling dekat dengan warga. Lihat apa yang terjadi, di mana dampaknya terasa, dan isu mana yang membutuhkan perhatian.</p></div><button class="btn-outline" data-public-view="problems">Lihat Semua Masalah →</button></div><div class="ipm-problem-grid">
 <article class="ipm-lead"><span class="ipm-badge">● PERHATIAN PUBLIK</span><h3>Masalah nyata harus terlihat sebelum dicari solusinya.</h3><p>Ruang utama portal menempatkan pokok masalah di depan agar masyarakat dapat memahami kondisi sebelum masuk ke data, perubahan, dan tindakan.</p><div class="ipm-metrics"><div class="ipm-metric"><b>38</b><span>Provinsi</span></div><div class="ipm-metric"><b>514</b><span>Kabupaten/Kota</span></div><div class="ipm-metric"><b>7.282</b><span>Kecamatan</span></div><div class="ipm-metric"><b>83.529</b><span>Desa/Kelurahan</span></div></div></article>`;
 data.forEach(x=>h+=`<article class="ipm-problem-card"><div class="ipm-thumb">${esc(x.icon)}</div><span class="ipm-tag">${esc(x.tag)}</span><h4>${esc(x.title)}</h4><p>${esc(x.meta)}</p></article>`);
 h+=`</div></section>
 <section class="ipm-section"><div class="ipm-voice"><div><span class="ipm-kicker" style="color:#b8c7d9">SUARA WARGA</span><h3>Setelah melihat masalah, mari dengarkan manusianya.</h3><p>Ceritakan pengalaman, beri konteks, atau sampaikan usulan. Setiap suara membantu pembaca memahami kondisi dari sudut pandang warga.</p></div><div class="ipm-actions"><button class="btn-primary" data-public-view="report">＋ Sampaikan Suara</button><button class="btn-outline" data-public-view="report">Lihat Percakapan →</button></div><div class="ipm-comment"><b>💬 Ayo ikut berkomentar</b><span>Tambahkan pendapat, pengalaman, atau informasi yang membantu masalah dibaca lebih lengkap.</span></div></div></section>
 <section class="ipm-section"><div class="ipm-head"><div><span class="ipm-kicker">PANTAU PERUBAHAN</span><h2>Apa yang berubah setelah dibicarakan?</h2><p>Ikuti masalah yang baru muncul, meningkat, menurun, ramai dibicarakan, atau membutuhkan perhatian.</p></div><button class="btn-outline" data-public-view="monitoring">Pantau Semua →</button></div><div class="ipm-grid-3"><article class="ipm-card"><div class="ico">↗</div><h3>Masalah yang ikut bergerak</h3><p>Perubahan ditampilkan berdasarkan waktu dan wilayah agar perkembangan tidak berhenti sebagai satu laporan.</p><button class="btn-outline" data-public-view="monitoring">Buka Pantauan →</button></article><article class="ipm-card"><div class="ico">⚠</div><h3>Tren & perhatian</h3><p>Lihat isu yang sedang naik, menurun, atau perlu diperhatikan lebih dekat.</p><button class="btn-outline" data-public-view="monitoring">Lihat Tren →</button></article><article class="ipm-card"><div class="ico">◌</div><h3>Ringkasan wilayah</h3><p>Bandingkan kondisi antarwilayah tanpa membawa istilah teknis ke ruang publik.</p><button class="btn-outline" data-public-view="regions">Jelajahi Wilayah →</button></article></div></section>
 <section class="ipm-section"><div class="ipm-split"><div class="ipm-visual"><div class="gridline"></div><div class="orbit"></div></div><div class="ipm-copy"><span class="ipm-kicker">INDONESIA DALAM SATU PANDANGAN</span><h3>Semakin dekat ke wilayah, semakin jelas masalahnya.</h3><p>Gunakan peta dan hierarki wilayah untuk berpindah dari Indonesia ke provinsi, kabupaten/kota, kecamatan, desa/kelurahan, hingga dusun.</p><div class="ipm-list"><div><b>Peta Indonesia</b><span>Jelajahi wilayah →</span></div><div><b>Data & Statistik</b><span>Lihat indikator →</span></div><div><b>Wawasan</b><span>Pahami pola →</span></div></div></div></div></section>
 <section class="ipm-section"><div class="ipm-grid-3"><article class="ipm-card"><div class="ico">◎</div><h3>Wawasan</h3><p>Pola, penyebab, tren, hubungan, dan ringkasan wilayah disajikan sebagai pengetahuan yang dapat dipahami.</p><button class="btn-outline" data-public-view="intelligence">Lihat Wawasan →</button></article><article class="ipm-card"><div class="ico">◇</div><h3>Kemungkinan</h3><p>Perkiraan, perbandingan, dan skenario untuk membantu melihat apa yang mungkin terjadi berikutnya.</p><button class="btn-outline" data-public-view="future">Lihat Kemungkinan →</button></article><article class="ipm-card"><div class="ico">✓</div><h3>Solusi & Aksi</h3><p>Temukan solusi warga, praktik baik, rekomendasi, dan hasil tindakan yang dapat dipelajari.</p><button class="btn-outline" data-public-view="solutions">Jelajahi Solusi →</button></article></div></section>
 <section class="ipm-cta"><h2>Lihat. Dengarkan. Pahami. Cari solusi.</h2><p>Satu ruang publik untuk memahami masalah Indonesia berdasarkan wilayah, data, suara masyarakat, perubahan, dan tindakan.</p><div class="ipm-cta-actions"><button class="btn-primary" data-public-view="report">Sampaikan Masalah</button><button class="btn-outline" data-public-view="map">Jelajahi Indonesia →</button></div></section></div>`;
 $('home').insertAdjacentHTML('beforeend',h);
 document.querySelectorAll('[data-public-view]').forEach(b=>b.addEventListener('click',()=>publicRender(b.dataset.publicView)));
}

