 solutions:{k:'SOLUSI',title:'Dari masalah menuju perubahan',desc:'Temukan solusi warga, solusi pemerintah, praktik baik, dan hasil tindakan yang dapat dipelajari.',cards:[['Solusi Warga','Gagasan dan tindakan yang lahir dari masyarakat.','🤝'],['Solusi Pemerintah','Kebijakan atau tindakan resmi yang relevan.','🏛️'],['Praktik Baik','Contoh pendekatan yang berhasil di tempat lain.','★'],['Evaluasi Hasil','Lihat apa yang berubah setelah sebuah tindakan.','✓']]}
