 const host=$(view);if(!host||!content)return;host.innerHTML=`<div class="page" style="max-width:1200px;margin:auto;padding:30px 28px 80px"><span class="ipm-kicker">${content.k}</span><h2 style="font-size:clamp(30px,4vw,48px);color:var(--ipm-navy);letter-spacing:-.04em;margin:8px 0">${content.title}</h2><p style="max-width:740px;color:#6c7b90;line-height:1.6">${content.desc}</p><div class="ipm-grid-3" style="margin-top:24px">${content.cards.map(c=>`<article class="ipm-card"><div class="ico">${c[2]}</div><h3>${c[0]}</h3><p>${c[1]}</p><button class="btn-outline" data-public-view="${view}">Jelajahi →</button></article>`).join('')}</div><div class="ipm-card" style="margin-top:16px"><h3>Ruang publik, bukan ruang teknis.</h3><p>Informasi teknis pengelolaan sistem tidak ditampilkan di halaman publik. Pengunjung cukup melihat hasil, konteks, sumber, perubahan, dan pilihan tindakan.</p></div></div>`;
 document.querySelectorAll('[data-public-view]').forEach(b=>b.onclick=()=>publicRender(b.dataset.publicView));setActive(view);
